CREATE TABLE IF NOT EXISTS gnw_outbox(id uuid PRIMARY KEY,tenant_id integer NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,topic text NOT NULL,payload jsonb NOT NULL,status text NOT NULL CHECK(status IN ('PENDING','PROCESSING','FAILED','QUARANTINED','SENT')),attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0),max_attempts integer NOT NULL DEFAULT 8 CHECK(max_attempts>0),available_at timestamptz NOT NULL DEFAULT now(),lease_owner text,lease_expires_at timestamptz,idempotency_key text NOT NULL,delivery_receipt text,last_error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,idempotency_key));CREATE INDEX IF NOT EXISTS gnw_outbox_claim_idx ON gnw_outbox(status,available_at,lease_expires_at);ALTER TABLE gnw_outbox ENABLE ROW LEVEL SECURITY;ALTER TABLE gnw_outbox FORCE ROW LEVEL SECURITY;DROP POLICY IF EXISTS gnw_outbox_tenant_policy ON gnw_outbox;CREATE POLICY gnw_outbox_tenant_policy ON gnw_outbox USING(tenant_id=current_setting('app.tenant_id',true)::integer) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::integer);
CREATE TABLE IF NOT EXISTS gnw_transition_idempotency(tenant_id integer NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,idempotency_key text NOT NULL,task_id integer NOT NULL,request_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,idempotency_key));ALTER TABLE gnw_transition_idempotency ENABLE ROW LEVEL SECURITY;ALTER TABLE gnw_transition_idempotency FORCE ROW LEVEL SECURITY;DROP POLICY IF EXISTS gnw_transition_tenant_policy ON gnw_transition_idempotency;CREATE POLICY gnw_transition_tenant_policy ON gnw_transition_idempotency USING(tenant_id=current_setting('app.tenant_id',true)::integer) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::integer);
